import base64, os


def ensure_font(path=None):
    if path is None:
        path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "font.ttf")
    if not os.path.exists(path) or os.path.getsize(path) < 1000:
        with open(path, "wb") as f:
            f.write(base64.b64decode("".join(DATA)))
    print("FONT READY:", path, os.path.getsize(path), flush=True)
    return path


